DROP VIEW IF EXISTS `image_details`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `image_details` AS SELECT
    `images`.`id` AS `image_id`,
    `images`.`path` AS `image_path`,
    `postimages`.`post_id` AS `post_id`,
    `postimages`.`is_primary` AS `is_primary`,
    `postimages`.`description` AS `description`
FROM
    `images`
        LEFT JOIN `postimages` ON `postimages`.`image_id` = `images`.`id`;

DROP VIEW IF EXISTS `view_sites`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_sites` AS SELECT `sites`.`id` AS `id`, `sites`.`name` AS `name`, `sites`.`description` AS `description`, `sites`.`sitetype` AS `sitetype`, `sites`.`latitude` AS `latitude`, `sites`.`longitude` AS `longitude`, `sites`.`elevation` AS `elevation`, `sites`.`rating` AS `rating`, `sites`.`facilities` AS `facilities`, `sites`.`created_on` AS `created_on`, `sites`.`updated_on` AS `updated_on`, JSON_ARRAYAGG(`postsites`.`groundtype`) as `groundtypes`, JSON_ARRAYAGG(`postsites`.`post_id`) as `post_ids` FROM `sites` LEFT JOIN `postsites` ON `postsites`.`site_id` = `sites`.`id` GROUP BY `sites`.`id`;

DROP VIEW IF EXISTS `view_posts`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_posts` AS SELECT `posts`.`id` AS `post_id`, `posts`.`type` AS `post_type`, `posts`.`title` AS `post_title`, `posts`.`content` AS `post_content`, `posts`.`content_markdown` AS `post_markdown`, `posts`.`visible` AS `post_visible`, `posts`.`view_count` AS `post_view_count`, `posts`.`created_on` AS `post_start_date`, `posts`.`end_date` AS `post_end_date`, IF ( `posts`.`type` = 'hike', ( SELECT json_arrayagg( json_object( 'hillId', `hills`.`id`, 'hillName', `hills`.`name`, 'hillType', `hills`.`type`, 'hillLatitude', `hills`.`latitude`, 'hillLongitude', `hills`.`longitude`, 'hillElevation', `hills`.`elevation`, 'hillSuccessful', `posthills`.`successful` )) FROM `posthills` LEFT JOIN `hills` ON `hills`.`id` = `posthills`.`hill_id` WHERE `posthills`.`post_id` = `posts`.`id` ), NULL ) AS `hills`, IF ( `posts`.`type` = 'hike', ( SELECT json_arrayagg( json_object( 'personId', `individuals`.`id`, 'personName', `individuals`.`name` )) from `individuals` left join `post_individuals` on `post_individuals`.`individual_id` = `individuals`.`id` where `post_individuals`.`post_id` = `posts`.`id`), NULL ) AS `people`, IF ( `posts`.`type` = 'hike', json_object( 'duration', `hikestats`.`duration`, 'distance', `hikestats`.`distance`, 'ascent', `hikestats`.`ascent`, 'gpx', `hikestats`.`gpx_path`, 'elevationProfile', `hikestats`.`elevation_profile_path`, 'timeDistanceProfile', `hikestats`.`time_distance_profile_path` ), NULL ) AS `hikeStats`, IF ( `posts`.`type` = 'hike', json_object( 'view', `hikeratings`.`view`, 'path', `hikeratings`.`path`, 'weather', `hikeratings`.`weather` ), NULL ) AS `hikeRating`,( SELECT json_arrayagg( `postvideos`.`video_path` ) FROM `postvideos` WHERE `postvideos`.`post_id` = `posts`.`id` GROUP BY `postvideos`.`post_id` ) AS `videos`,( SELECT json_arrayagg( `storyposts`.`story_id` ) FROM `storyposts` WHERE `storyposts`.`post_id` = `posts`.`id` GROUP BY `storyposts`.`post_id` ) AS `story_ids`,( SELECT json_arrayagg( json_object( 'imageId', `images`.`id`, 'imagePath', `images`.`path`, 'imageIsPrimary', `postimages`.`is_primary`, 'imageDescription', `postimages`.`description` )) FROM `postimages` LEFT JOIN `images` ON `images`.`id` = `postimages`.`image_id` WHERE `postimages`.`post_id` = `posts`.`id` GROUP BY `postimages`.`post_id` ) AS `images`, ( SELECT json_arrayagg( json_object( 'siteId', `sites`.`id`, 'siteName', `sites`.`name`, 'siteDescription', `sites`.`description`, 'siteType', `sites`.`sitetype`, 'siteLatitude', `sites`.`latitude`, 'siteLongitude', `sites`.`longitude`, 'siteRating', `sites`.`rating`, 'siteFacilities', `sites`.`facilities`, 'groundType', `postsites`.`groundtype` )) FROM `postsites` LEFT JOIN `sites` ON `sites`.`id` = `postsites`.`site_id` WHERE `postsites`.`post_id` = `posts`.`id` GROUP BY `postsites`.`post_id` ) AS `sites` FROM `posts` LEFT JOIN `posthills` ON `posthills`.`post_id` = `posts`.`id` LEFT JOIN `hills` ON `posthills`.`hill_id` = `hills`.`id` LEFT JOIN `post_individuals` ON `post_individuals`.`post_id` = `posts`.`id` LEFT JOIN `individuals` ON `post_individuals`.`individual_id` = `individuals`.`id` LEFT JOIN `hikestats` ON `hikestats`.`post_id` = `posts`.`id` LEFT JOIN `hikeratings` ON `hikeratings`.`post_id` = `posts`.`id` GROUP BY `posts`.`id`;

DROP VIEW IF EXISTS `view_hills`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_hills` AS SELECT `id` AS `hill_id`, `name` AS `hill_name`, `type` AS `hill_type`, `region` AS `hill_region`, `url` AS `hill_url`, `latitude` AS `hill_latitude`, `longitude` AS `hill_longitude`, `elevation` AS `hill_elevation`, ( SELECT JSON_ARRAYAGG( JSON_OBJECT( 'id', `posts`.`id`, 'title', `posts`.`title`, 'primaryImageId', `images`.`id`, 'primaryImagePath', `images`.`path`, 'visible', `posts`.`visible` , 'type', `posts`.`type` )) FROM `posts` LEFT JOIN `postimages` ON ( `posts`.`id` = `postimages`.`post_id` AND `postimages`.`is_primary` = 1 ) LEFT JOIN `images` ON `images`.`id` = `postimages`.`image_id` LEFT JOIN `posthills` ON `posthills`.`post_id` = `posts`.`id` WHERE `posthills`.`hill_id` = `hills`.`id` ) AS `posts`, ( SELECT JSON_ARRAYAGG( JSON_OBJECT( 'personId', `individuals`.`id`, 'personName', `individuals`.`name` )) FROM `posts` LEFT JOIN `post_individuals` ON `posts`.`id` = `post_individuals`.`post_id` LEFT JOIN `individuals` ON `individuals`.`id` = `post_individuals`.`individual_id` LEFT JOIN `posthills` ON `posthills`.`post_id` = `posts`.`id` WHERE `posthills`.`hill_id` = `hills`.`id` ) AS `people` FROM hills;

DROP VIEW IF EXISTS `view_stories`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `view_stories` AS SELECT `stories`.`id` AS `story_id`, `stories`.`title` AS `story_title`, `stories`.`content` AS `story_content`, `stories`.`content_markdown` AS `story_markdown`, `stories`.`created_on` AS `story_start_date`,( SELECT json_arrayagg( json_object( 'id', `posts`.`id`, 'title', `posts`.`title`, 'primaryImageId', `images`.`id`, 'primaryImagePath', `images`.`path`, 'visible', `posts`.`visible` , 'type', `posts`.`type` )) FROM `posts` LEFT JOIN `postimages` ON ( `posts`.`id` = `postimages`.`post_id` AND `postimages`.`is_primary` = 1 ) LEFT JOIN `images` ON `images`.`id` = `postimages`.`image_id` LEFT JOIN `storyposts` ON `storyposts`.`post_id` = `posts`.`id` WHERE `storyposts`.`story_id` = `stories`.`id` ) AS `posts` FROM `stories`;
